import numpy as np

def make_input(agent, ball, prev_cells):
    x = np.zeros((10,10,5))
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                x[r,c,3] = 1
    for (r,c) in agent: x[r,c,0] = 1
    for (r,c) in ball:  x[r,c,1] = 1
    for (r,c) in prev_cells: x[r,c,4] = 1
    return x.flatten()

agent = [(8,5)]
rows=[]; names=[]
rows.append(make_input(agent, [], [(8,5)])); names.append('noball')
for col in [3,5,7]:
    for prevcol, tag in [(col,'static'), (col-1,'right'), (col+1,'left')]:
        rows.append(make_input(agent, [(7,col)], [(8,5),(7,prevcol)]))
        names.append(f'c{col}_{tag}')

X = np.array(rows)
out = forward(X)
for i,name in enumerate(names):
    lg = out[i]
    print(f'{name:12s} lr={lg[3]-lg[4]:7.2f}  ud={lg[1]-lg[2]:6.2f}  logits={np.round(lg,1)}')
